SET NOCOUNT ON;
SET XACT_ABORT ON;
USE [master];
IF DB_ID(N'ibcmd_rs_05_online_a1') IS NULL THROW 57230, 'live activation database does not exist', 1;
IF (SELECT recovery_model FROM sys.databases WHERE name=N'ibcmd_rs_05_online_a1') NOT IN (1,2) THROW 57231, 'live activation requires FULL or BULK_LOGGED recovery', 1;
IF (SELECT state FROM sys.databases WHERE name=N'ibcmd_rs_05_online_a1') <> 0 THROW 57232, 'live activation requires an ONLINE database', 1;
IF EXISTS (SELECT 1 FROM sys.dm_os_file_exists(N'F:\ibcmd\lab\05\online\bak\ibcmd_rs_05_online_a1_tail5.trn') WHERE file_exists=1 OR file_is_a_directory=1) THROW 57233, 'tail-log output already exists or is a directory', 1;
USE [ibcmd_rs_05_online_a1];
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @LockResult int;
EXEC @LockResult = sys.sp_getapplock @Resource=N'ibcmd-rs:main-activation', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=0;
IF @LockResult < 0 THROW 57200, 'main activation application lock is busy', 1;
DECLARE @ExpectedStage TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedStage VALUES (N'b27aebc8-f190-4658-a81d-fd1406905f39',0, 176,0x0FF3435CE435C2F379D462B42F4F08BE10D1530E0691FEF513174387F3E1A3BF);
INSERT @ExpectedStage VALUES (N'b27aebc8-f190-4658-a81d-fd1406905f39.0',0, 450,0xE923B91EA103F2332A686A67C657F43B1A06897DC57BBC66CCB448B29D57AFD3);
INSERT @ExpectedStage VALUES (N'root',0, 45,0xADFE2E91D2EFB05910281F6EFBB026ADFA876AA812D082C7F9E755028632A256);
INSERT @ExpectedStage VALUES (N'version',0, 28,0xEC6D68D22CDFA563A8FA7B32B6C827ABC9B84B1C0FEBC543EFC70E450459B795);
INSERT @ExpectedStage VALUES (N'versions',0, 344207,0xB0A182D1C73B383A9DE312806148A8A6CCB8602623AA6453AE8AA1E4FCE62425);
DECLARE @ExpectedActive TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedActive VALUES (N'b27aebc8-f190-4658-a81d-fd1406905f39',0, 173,0x818F2FC535E6940753B3650BD5F8A2BF872419A7E6E3DCB35D1D9BA346BD6D6F);
INSERT @ExpectedActive VALUES (N'b27aebc8-f190-4658-a81d-fd1406905f39.0',0, 492,0xCFC2B23D853F479AC7C2654EE6ABE567482084B568AAEC08768438F3F51905AD);
INSERT @ExpectedActive VALUES (N'root',0, 45,0xADFE2E91D2EFB05910281F6EFBB026ADFA876AA812D082C7F9E755028632A256);
INSERT @ExpectedActive VALUES (N'version',0, 28,0xEC6D68D22CDFA563A8FA7B32B6C827ABC9B84B1C0FEBC543EFC70E450459B795);
INSERT @ExpectedActive VALUES (N'versions',0, 340602,0x1E15F7BFA97DC63B17CCFDC353DCDFF15F907CFAB3D0A2E770CF30B633F683FA);
IF EXISTS (SELECT FileName,PartNo,CONVERT(bigint,DataSize),HASHBYTES('SHA2_256',BinaryData) FROM dbo.ConfigSave WITH (UPDLOCK,HOLDLOCK) EXCEPT SELECT FileName,PartNo,DataSize,Digest FROM @ExpectedStage) OR EXISTS (SELECT FileName,PartNo,DataSize,Digest FROM @ExpectedStage EXCEPT SELECT FileName,PartNo,CONVERT(bigint,DataSize),HASHBYTES('SHA2_256',BinaryData) FROM dbo.ConfigSave WITH (UPDLOCK,HOLDLOCK)) THROW 57201, 'ConfigSave exact snapshot drifted', 1;
IF EXISTS (SELECT E.FileName,E.PartNo FROM @ExpectedActive E LEFT JOIN dbo.Config T WITH (UPDLOCK,HOLDLOCK) ON T.FileName=E.FileName AND T.PartNo=E.PartNo AND CONVERT(bigint,T.DataSize)=E.DataSize AND HASHBYTES('SHA2_256',T.BinaryData)=E.Digest WHERE T.FileName IS NULL) THROW 57202, 'Config selected snapshot drifted', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated') <> 1 OR (SELECT COUNT_BIG(*) FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 AND CONVERT(bigint,DataSize)=82 AND HASHBYTES('SHA2_256',BinaryData)=0x6CCA7BB82241678CA1AA120C28A06E61CD0A87B7F80EED7C458EA82748C61B2E) <> 1 THROW 57203, 'Config.DynamicallyUpdated drifted', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.Params WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated') <> 1 OR (SELECT COUNT_BIG(*) FROM dbo.Params WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 AND CONVERT(bigint,DataSize)=119 AND HASHBYTES('SHA2_256',BinaryData)=0xD929C5543C4D55151DF336FAFD10E35816D23A98AB463EACF08710F41344FAF7) <> 1 THROW 57204, 'Params.DynamicallyUpdated drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'b27aebc8-f190-4658-a81d-fd1406905f39' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'b27aebc8-f190-4658-a81d-fd1406905f39' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'b27aebc8-f190-4658-a81d-fd1406905f39.0' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'b27aebc8-f190-4658-a81d-fd1406905f39.0' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'root' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'root' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'version' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'version' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'versions' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'versions' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57210, 'exclusive promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'DynamicallyUpdated';
IF @@ROWCOUNT <> 1 THROW 57215, 'Config.DynamicallyUpdated cleanup drifted', 1;
DELETE FROM dbo.Params WHERE FileName=N'DynamicallyUpdated';
IF @@ROWCOUNT <> 1 THROW 57216, 'Params.DynamicallyUpdated cleanup drifted', 1;
DELETE FROM dbo.ConfigSave;
IF @@ROWCOUNT <> 5 THROW 57220, 'ConfigSave cleanup drifted', 1;
DECLARE @ExpectedPublished TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedPublished VALUES (N'b27aebc8-f190-4658-a81d-fd1406905f39',0, 176,0x0FF3435CE435C2F379D462B42F4F08BE10D1530E0691FEF513174387F3E1A3BF);
INSERT @ExpectedPublished VALUES (N'b27aebc8-f190-4658-a81d-fd1406905f39.0',0, 450,0xE923B91EA103F2332A686A67C657F43B1A06897DC57BBC66CCB448B29D57AFD3);
INSERT @ExpectedPublished VALUES (N'root',0, 45,0xADFE2E91D2EFB05910281F6EFBB026ADFA876AA812D082C7F9E755028632A256);
INSERT @ExpectedPublished VALUES (N'version',0, 28,0xEC6D68D22CDFA563A8FA7B32B6C827ABC9B84B1C0FEBC543EFC70E450459B795);
INSERT @ExpectedPublished VALUES (N'versions',0, 344207,0xB0A182D1C73B383A9DE312806148A8A6CCB8602623AA6453AE8AA1E4FCE62425);
IF EXISTS (SELECT E.FileName,E.PartNo FROM @ExpectedPublished E LEFT JOIN dbo.Config T WITH (UPDLOCK,HOLDLOCK) ON T.FileName=E.FileName AND T.PartNo=E.PartNo AND CONVERT(bigint,T.DataSize)=E.DataSize AND HASHBYTES('SHA2_256',T.BinaryData)=E.Digest WHERE T.FileName IS NULL) THROW 57222, 'Config selected snapshot drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WHERE FileName=N'DynamicallyUpdated') THROW 57225, 'Config.DynamicallyUpdated cleanup postcondition failed', 1;
IF EXISTS (SELECT 1 FROM dbo.Params WHERE FileName=N'DynamicallyUpdated') THROW 57226, 'Params.DynamicallyUpdated cleanup postcondition failed', 1;
IF EXISTS (SELECT 1 FROM dbo.ConfigSave) THROW 57221, 'ConfigSave postcondition failed', 1;
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
THROW;
END CATCH;
DECLARE @LiveExpected1cConnections int=(SELECT COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process=1 AND database_id=DB_ID(N'ibcmd_rs_05_online_a1') AND program_name=N'1CV83 Server');
CHECKPOINT;
USE [master];
BEGIN TRY
ALTER DATABASE [ibcmd_rs_05_online_a1] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
BACKUP LOG [ibcmd_rs_05_online_a1] TO DISK=N'F:\ibcmd\lab\05\online\bak\ibcmd_rs_05_online_a1_tail5.trn' WITH NORECOVERY, INIT, COMPRESSION, CHECKSUM;
RESTORE DATABASE [ibcmd_rs_05_online_a1] WITH RECOVERY;
ALTER DATABASE [ibcmd_rs_05_online_a1] SET MULTI_USER;
DECLARE @LiveReconnectDeadline datetime2(3)=DATEADD(millisecond,4000,SYSUTCDATETIME()), @LiveStableSince datetime2(3)=NULL, @LiveObserved1cConnections int=0;
WHILE @LiveExpected1cConnections > 0 AND SYSUTCDATETIME() < @LiveReconnectDeadline BEGIN SELECT @LiveObserved1cConnections=COUNT(*) FROM sys.dm_exec_sessions WHERE is_user_process=1 AND database_id=DB_ID(N'ibcmd_rs_05_online_a1') AND program_name=N'1CV83 Server'; IF @LiveObserved1cConnections >= @LiveExpected1cConnections BEGIN IF @LiveStableSince IS NULL SET @LiveStableSince=SYSUTCDATETIME(); IF DATEDIFF(millisecond,@LiveStableSince,SYSUTCDATETIME()) >= 500 BREAK; END ELSE SET @LiveStableSince=NULL; WAITFOR DELAY '00:00:00.100'; END;
IF @LiveExpected1cConnections > 0 AND (@LiveObserved1cConnections < @LiveExpected1cConnections OR @LiveStableSince IS NULL OR DATEDIFF(millisecond,@LiveStableSince,SYSUTCDATETIME()) < 500) THROW 57234, '1C SQL connections did not recover before the live activation deadline; database is online and the second recovery was not started', 1;
ALTER DATABASE [ibcmd_rs_05_online_a1] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
BACKUP LOG [ibcmd_rs_05_online_a1] TO DISK=N'F:\ibcmd\lab\05\online\bak\ibcmd_rs_05_online_a1_tail5.trn' WITH NORECOVERY, NOINIT, COMPRESSION, CHECKSUM;
RESTORE DATABASE [ibcmd_rs_05_online_a1] WITH RECOVERY;
ALTER DATABASE [ibcmd_rs_05_online_a1] SET MULTI_USER;
END TRY
BEGIN CATCH
IF DB_ID(N'ibcmd_rs_05_online_a1') IS NOT NULL AND DATABASEPROPERTYEX(N'ibcmd_rs_05_online_a1','Status') <> N'RESTORING' ALTER DATABASE [ibcmd_rs_05_online_a1] SET MULTI_USER;
IF DB_ID(N'ibcmd_rs_05_online_a1') IS NOT NULL AND DATABASEPROPERTYEX(N'ibcmd_rs_05_online_a1','Status') = N'RESTORING' BEGIN DECLARE @LiveRecoveryMessage nvarchar(2048)=N'live activation left database restoring; run RESTORE DATABASE [ibcmd_rs_05_online_a1] WITH RECOVERY; original error: '+ERROR_MESSAGE(); THROW 57250,@LiveRecoveryMessage,1; END;
THROW;
END CATCH;
